INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',10,NULL,'choice','{"stem":"\"I can''t hear a word!\" 表达的是:","options":["声音太小需要道歉","想学新单词","一个字都听不见","不识字"],"answer_index":2}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',10,NULL,'choice','{"stem":"Where did the young couple sit?","options":["Behind the writer.","On the stage.","In front of the writer.","Next to the actors."],"answer_index":0,"passage":"Last Friday I went to the theater downtown. I had a great seat, right in the center. The play was a comedy, and it was really funny. But I didn''t enjoy it at all. A young couple was sitting behind me, and they were talking loudly the whole time. I got angry because I couldn''t hear the actors. I turned around and looked at them, but they didn''t pay any attention. In the end I couldn''t bear it. I turned around again. \"I can''t hear a word!\" I said angrily. \"It''s none of your business,\" the young man said rudely. \"This is a private conversation!\""}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',10,NULL,'choice','{"stem":"Why didn''t the writer enjoy the play?","options":["The play was boring.","He arrived late.","He couldn''t hear the actors.","The seat was bad."],"answer_index":2,"passage":"Last Friday I went to the theater downtown. I had a great seat, right in the center. The play was a comedy, and it was really funny. But I didn''t enjoy it at all. A young couple was sitting behind me, and they were talking loudly the whole time. I got angry because I couldn''t hear the actors. I turned around and looked at them, but they didn''t pay any attention. In the end I couldn''t bear it. I turned around again. \"I can''t hear a word!\" I said angrily. \"It''s none of your business,\" the young man said rudely. \"This is a private conversation!\""}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',10,NULL,'choice','{"stem":"How did the writer feel during the play?","options":["Angry.","Happy.","Scared.","Bored."],"answer_index":0,"audio":"Last Friday I went to the theater downtown. I had a great seat, right in the center. The play was a comedy, and it was really funny. But I didn''t enjoy it at all. A young couple was sitting behind me, and they were talking loudly the whole time. I got angry because I couldn''t hear the actors. I turned around and looked at them, but they didn''t pay any attention. In the end I couldn''t bear it. I turned around again. \"I can''t hear a word!\" I said angrily. \"It''s none of your business,\" the young man said rudely. \"This is a private conversation!\""}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',10,NULL,'choice','{"stem":"What kind of play was it?","options":["A musical.","A mystery.","A comedy.","A tragedy."],"answer_index":2,"audio":"Last Friday I went to the theater downtown. I had a great seat, right in the center. The play was a comedy, and it was really funny. But I didn''t enjoy it at all. A young couple was sitting behind me, and they were talking loudly the whole time. I got angry because I couldn''t hear the actors. I turned around and looked at them, but they didn''t pay any attention. In the end I couldn''t bear it. I turned around again. \"I can''t hear a word!\" I said angrily. \"It''s none of your business,\" the young man said rudely. \"This is a private conversation!\""}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l02',2,1,2,'Breakfast or lunch?','早餐还是午餐?','一般现在时 vs 现在进行时 · V-ing拼写 · 频度副词 · What/How感叹句','懒觉的周日 · 姑妈来电,"一点钟还在吃早餐"','{"q":"Listen and answer — Why is the writer''s aunt surprised?","options":["He is still sleeping","He is still having breakfast at one o''clock","He is not at home","He is late for the train"],"answer_index":1}'::jsonb,'{"title":"现在的两种时态(用本课句子看懂它)","intro":"本课要分清两种\"现在\":经常做的事,还是此刻正在做的事。下面全用本课句子举例。","table":{"headers":["时态","什么时候用 · 本课例子"],"rows":[["一般现在时(动词原形 / 第三人称 +s)","说经常、习惯、每天的事:I never get up early on Sundays.(周日从不早起=习惯)"],["一般现在时也说客观事实","The sun rises in the east.(太阳东升=永远的事实)"],["现在进行时(am/is/are + V-ing)","说此刻正在做的事:I''m having breakfast.(此刻正在吃)"],["现在进行时也说近期安排","I''m coming over tonight.(近期打算来=已安排好)"]]},"specialRules":[{"rule":"V-ing 拼写:一般直接加 -ing;去掉不发音的 e(have→having);重读闭音节末尾单辅音字母双写(run→running);ie→y(lie→lying)","mark":"拼写"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l02',1,NULL,'It was Sunday, and I was still fast asleep.','那是个星期天,我还在呼呼大睡。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l02',2,NULL,'I never get up early on Sundays — I usually stay in bed until noon.','周日我从来不早起——通常会赖床到中午。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l02',3,NULL,'That morning it was raining, and it was dark outside.','那天早上在下雨,外面一片昏暗。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l02',4,NULL,'"What a lazy Sunday!" I thought.','"多懒的一个周日啊!"我心想。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l02',5,NULL,'Then my cell phone rang.','这时我的手机响了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l02',6,NULL,'It was my aunt Kate; I''m her only nephew, so she calls me every weekend.','是我姑妈凯特;我是她唯一的外甥,所以她每个周末都给我打电话。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l02',7,NULL,'"I just arrived by train," she said. "I''m coming over to see you right now!"','"我刚坐火车到,"她说,"我这就过来看你!"') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l02',8,NULL,'"But I''m still having breakfast," I said.','"可我还在吃早餐呢,"我说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l02',9,NULL,'"Breakfast? What are you doing?" she asked.','"早餐?你在干什么?"她问道。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l02',10,NULL,'"I''m having breakfast," I repeated.','"我在吃早餐,"我又说了一遍。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l02',11,NULL,'"Oh my!" she said. "Do you always get up this late? It''s already one o''clock!"','"天哪!"她说,"你总是起这么晚吗?已经一点钟了!"') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l02',12,NULL,'For me, breakfast is the first meal of the day — even at lunchtime.','对我来说,早餐是一天的第一顿饭——哪怕在午饭时间吃。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
