INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l04','different','/ˈdɪfrənt/','adj','不同的','He has traveled to many different cities.') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
