INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l04_gp3','am2_l04','现在完成时——just/already 位置',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l04_gp4','am2_l04','现在完成时——never/ever 表经历',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l04_gp5','am2_l04','现在完成时——yet(否定/疑问句末)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l04_gp6','am2_l04','现在完成时——for+时间段',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l04_gp7','am2_l04','have gone vs have been',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l04_gp8','am2_l04','现在完成时 vs 一般过去时',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l04_gp9','am2_l04','现在进行时 vs 现在完成时',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l04','center','centre','中心;美语 -er 结尾 center,英式 -re 结尾 centre;同类 theater/theatre') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l04','gotten','got','get 的过去分词;美语现在完成时用 has gotten,英式用 has got') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l04','traveled','travelled','travel 的过去式/过去分词;美语单 l,英式双 l') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l04','a great number of','',NULL,'/ə ɡreɪt ˈnʌmbər əv/','He has visited a great number of different cities.','他去过许多不同的城市。','A great number of people came.','来了很多人。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l04','for six months','',NULL,'/fɔːr sɪks mʌnθs/','He has been there for six months.','他已经在那儿待了六个月了。','I have studied English for six months.','我学英语已经六个月了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l04','in the center of','',NULL,'/ɪn ðə ˈsentər əv/','a small town in the center of the country','位于这个国家中心的一个小镇','The hotel is in the center of the city.','这家酒店在市中心。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',5,'am2_l04_gp1','choice','{"stem":"\"I ___ just received a letter.\"(主语 I,填 have 还是 has)","options":["have","was","has","am"],"answer_index":0,"explanation_cn":"现在完成时 = have/has + 过去分词。主语 I(还有 you/we/they)用 have。✓ I have just received a letter."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',5,'am2_l04_gp1','choice','{"stem":"\"He ___ already visited many cities.\"(主语 He)","options":["did","is","has","have"],"answer_index":2,"explanation_cn":"主语 He(还有 she/it)用 has。✓ He has already visited many cities."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',5,'am2_l04_gp2','choice','{"stem":"\"I have just ___ a letter from Tom.\"(receive 的过去分词)","options":["receive","received","receiving","receives"],"answer_index":1,"explanation_cn":"receive 是规则动词,过去分词直接加 -d → received(与它的过去式同形)。✓ I have just received a letter."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',5,'am2_l04_gp2','choice','{"stem":"\"He has ___ to Alice Springs.\"(go 的过去分词)","options":["goed","went","going","gone"],"answer_index":3,"explanation_cn":"go 是不规则动词,过去分词是 gone(不是 went,也不是 goed)。✓ He has gone to Alice Springs."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',5,'am2_l04_gp2','choice','{"stem":"下列哪个动词的过去分词是不规则的(不是直接加 -ed)?","options":["arrive → arrived","buy → bought","visit → visited","receive → received"],"answer_index":1,"explanation_cn":"规则动词的过去分词直接加 -ed(visit→visited / receive→received / arrive→arrived);只有 buy→bought 要单独记,是不规则的。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',5,'am2_l04_gp3','choice','{"stem":"把 just 放到正确位置:\"I have had breakfast.\"(我刚吃过早饭)","options":["I have had breakfast just.","I have had just breakfast.","I have just had breakfast.","I just have had breakfast."],"answer_index":2,"explanation_cn":"just 要放在 have 和过去分词 had 中间。✓ I have just had breakfast. 既不放句首,也不放句尾。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',5,'am2_l04_gp3','choice','{"stem":"just / already / never 在现在完成时里的位置一般是:","options":["在句子最后面","在主语前面","在句子最前面","在 have/has 和过去分词中间"],"answer_index":3,"explanation_cn":"just / already / never 这类词,位置在 have/has 和过去分词之间。✓ He has already gotten a job. / I have never been there."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',5,'am2_l04_gp4','choice','{"stem":"\"___ you ever been to Canada?\"(问对方去过没有)","options":["Have","Are","Did","Has"],"answer_index":0,"explanation_cn":"现在完成时的疑问句把 have/has 提到主语前面;you 用 Have。✓ Have you ever been to Canada?"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',5,'am2_l04_gp4','choice','{"stem":"\"My brother has ___ been abroad before.\"(从来没有)","options":["yet","ever","just","never"],"answer_index":3,"explanation_cn":"\"从来没有\"用 never,放在 has 和过去分词中间。✓ My brother has never been abroad before."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',5,'am2_l04_gp5','choice','{"stem":"\"The train has not arrived ___ .\"(火车还没到)","options":["just","yet","already","ever"],"answer_index":1,"explanation_cn":"yet 表示\"还(没)\",用在否定句末。✓ The train has not arrived yet."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',5,'am2_l04_gp5','choice','{"stem":"\"Have you finished your homework ___ ?\"(问''……了吗'')","options":["ever","already","yet","since"],"answer_index":2,"explanation_cn":"yet 也用在疑问句末,表示\"……了吗\"。✓ Have you finished your homework yet?"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',5,'am2_l04_gp6','choice','{"stem":"\"He has been there ___ six months.\"(达六个月)","options":["at","for","since","in"],"answer_index":1,"explanation_cn":"\"达六个月\"是一段时间,用 for + 时间段。✓ He has been there for six months. since 后面接的是过去的时间点(如 since 1980)。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',5,'am2_l04_gp6','choice','{"stem":"选出正确的一句(他在这儿住了三年了):","options":["He has lived here for three years.","He has lived here since three years.","He is living here for three years.","He lives here for three years."],"answer_index":0,"explanation_cn":"现在完成时 + for + 时间段表示\"到现在为止一直……\"。✓ He has lived here for three years. 注意不能说 since three years(要说 since three years ago)。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',5,'am2_l04_gp7','choice','{"stem":"\"Tom has ___ to Alice Springs.\"(他去了,现在还没回来)","options":["been","went","gone","being"],"answer_index":2,"explanation_cn":"has gone 表示\"去了那儿、现在还没回来\"。✓ Tom has gone to Alice Springs.(人还在那)"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',5,'am2_l04_gp7','choice','{"stem":"\"He has gone to Canada\" 和 \"He has been to Canada\" 的区别是:","options":["两句意思完全一样","gone 指将来,been 指过去","gone=去过回来了;been=去了没回","gone=去了还没回;been=去过又回来了"],"answer_index":3,"explanation_cn":"has gone to = 去了那里、人还没回来;has been to = 去过那里、现在已经回来了。这是两者最大的区别。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',5,'am2_l04_gp8','choice','{"stem":"选出用现在完成时、强调\"对现在的结果\"的一句:","options":["He has broken his leg, so he can''t walk now.","He breaks his leg every winter.","He is breaking his leg.","He broke his leg last year."],"answer_index":0,"explanation_cn":"现在完成时强调\"过去的动作对现在造成的结果\":他把腿摔断了,所以现在走不了路。✓ 其它几句要么是一般过去时(last year),要么是习惯或正在进行。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',5,'am2_l04_gp8','choice','{"stem":"\"我去年去了加拿大\"(有明确过去时间 last year)应该说:","options":["I have gone to Canada last year.","I have been to Canada last year.","I go to Canada last year.","I went to Canada last year."],"answer_index":3,"explanation_cn":"有明确的过去时间 last year,就用一般过去时,不能用现在完成时。✓ I went to Canada last year.(现在完成时不和 yesterday/last year 这类明确过去时间连用)"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',5,'am2_l04_gp9','choice','{"stem":"\"The bell ___ .\"(铃刚刚响过,现在停了)","options":["has just rung","is ringing","rang just","rings"],"answer_index":0,"explanation_cn":"铃\"刚刚响过、现在停了\",看的是对现在的结果,用现在完成时 has just rung。✓ The bell has just rung. is ringing 是\"正在响\",意思不同。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',6,NULL,'choice','{"stem":"美语里\"中心\"的拼写是:","options":["centre","senter","cencer","center"],"answer_index":3,"explanation_cn":"美语\"中心\"拼作 center(-er 结尾);英式拼 centre(-re 结尾)。✓ in the center of the city."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',6,NULL,'choice','{"stem":"get 的过去分词,美式常用:\"He has ___ a new car.\"","options":["getted","got","gotten","goten"],"answer_index":2,"explanation_cn":"get 的过去分词,美语常用 gotten。✓ He has gotten a new car. 英式则说 has got。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',6,NULL,'choice','{"stem":"travel(旅行)的过去分词,美式拼写是:","options":["travled","traveled","traveleded","travelled"],"answer_index":1,"explanation_cn":"美语里 travel 加词尾只单写一个 l → traveled;英式双写 → travelled。✓ He has traveled a lot."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',6,NULL,'choice','{"stem":"a great number of 的意思是:","options":["只有几个","一半","一点点","许多(修饰可数名词复数)"],"answer_index":3,"explanation_cn":"a great number of = 许多,后面接可数名词复数。✓ a great number of cities."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',6,NULL,'choice','{"stem":"for six months 表示:","options":["六个月前","在六月份","达六个月(一段时间)","第六个月"],"answer_index":2,"explanation_cn":"for six months = 达六个月,表示一段持续的时间。✓ He has been there for six months."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',6,NULL,'choice','{"stem":"in the center of the country 的意思是:","options":["在国家外面","去这个国家","在国家旁边","在这个国家的中心"],"answer_index":3,"explanation_cn":"in the center of the country = 在这个国家的中心位置。✓ a town in the center of the country."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',7,NULL,'cloze','{"stem":"第 1 空","context":"My brother Tom has moved abroad. I have just ___1___ a letter from him. He has ___2___ there for six months. He has ___3___ gotten a good job. Right now he has ___4___ to a small town.","blank_no":1,"options":["received","receive","receiving","receives"],"answer_index":0,"explanation_cn":"\"我刚收到一封信\"用现在完成时 have received;receive 的过去分词是 received。✓ I have just received a letter."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',7,NULL,'cloze','{"stem":"第 2 空","context":"My brother Tom has moved abroad. I have just ___1___ a letter from him. He has ___2___ there for six months. He has ___3___ gotten a good job. Right now he has ___4___ to a small town.","blank_no":2,"options":["been","be","was","being"],"answer_index":0,"explanation_cn":"\"在那儿待了六个月\"用 has been there;be 的过去分词是 been。✓ He has been there for six months."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',7,NULL,'cloze','{"stem":"第 3 空","context":"My brother Tom has moved abroad. I have just ___1___ a letter from him. He has ___2___ there for six months. He has ___3___ gotten a good job. Right now he has ___4___ to a small town.","blank_no":3,"options":["already","yet","ever","since"],"answer_index":0,"explanation_cn":"\"已经找到了好工作\"用 already,放在 has 和过去分词中间。✓ He has already gotten a good job."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',7,NULL,'cloze','{"stem":"第 4 空","context":"My brother Tom has moved abroad. I have just ___1___ a letter from him. He has ___2___ there for six months. He has ___3___ gotten a good job. Right now he has ___4___ to a small town.","blank_no":4,"options":["driven","drove","drive","driving"],"answer_index":0,"explanation_cn":"\"开车去了小镇\"用 has driven;drive 的过去分词是 driven(不是 drove)。✓ He has driven to a small town."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',8,NULL,'choice','{"stem":"Where is Tom now?","options":["In Australia","In Canada","In France","In Italy"],"answer_index":1,"explanation_cn":"课文说 He is now living in Canada,Tom 现在在加拿大。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',8,NULL,'choice','{"stem":"How long has Tom been abroad?","options":["A year","Three months","Six months","Two weeks"],"answer_index":2,"explanation_cn":"课文说 he has been there for six months,他已经在国外待了六个月。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',8,NULL,'choice','{"stem":"Has Tom been abroad before?","options":["No, he has never been abroad before","Yes, once","No, he is still at home","Yes, many times"],"answer_index":0,"explanation_cn":"课文说 Tom has never lived abroad before,他以前从没在国外生活过。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',9,NULL,'choice','{"stem":"你刚吃完午饭,想说\"我刚吃过午饭\":","options":["I just having lunch.","I just have had lunch.","I have had lunch yet.","I have just had lunch."],"answer_index":3,"explanation_cn":"说\"刚刚做完\"的事用 have just done。✓ I have just had lunch. 场合:别人问你吃了没,你告诉他刚吃过。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',9,NULL,'choice','{"stem":"你想问朋友\"你去过加拿大吗\"(问经历):","options":["Are you ever been to Canada?","Have you ever been to Canada?","Did you ever been to Canada?","Do you ever go to Canada?"],"answer_index":1,"explanation_cn":"问别人\"有没有去过某地\"(问经历)用 Have you ever been to…?。✓ Have you ever been to Canada? 场合:聊到旅行时问对方去没去过。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',9,NULL,'choice','{"stem":"你想说\"我学英语已经三年了\"(一直持续到现在):","options":["I have learned English for three years.","I have learned English since three years.","I learn English for three years.","I am learning English for three years ago."],"answer_index":0,"explanation_cn":"说\"一直做某事、持续了多久\"用 have done + for + 一段时间。✓ I have learned English for three years. 注意别说 since three years。场合:介绍自己学了多久英语。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',10,NULL,'choice','{"stem":"课文里 firm 的意思是:","options":["农场","签名","坚固的","公司"],"answer_index":3,"explanation_cn":"firm 在课文里是\"公司\"的意思。✓ He works at a big firm. 不是\"农场\",也不是\"坚固的\"。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',10,NULL,'choice','{"stem":"go abroad 的意思是:","options":["出国,去国外","走开","上船","登机"],"answer_index":0,"explanation_cn":"go abroad = 出国、去国外。✓ Tom has moved abroad."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',10,NULL,'choice','{"stem":"\"I ___ finished my homework.\"(现在完成时,主语 I)","options":["am","has","have","did"],"answer_index":2,"explanation_cn":"主语 I 用 have + 过去分词。✓ I have finished my homework."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',10,NULL,'choice','{"stem":"\"He has ___ to the store; he''ll be back soon.\"(去了还没回)","options":["gone","being","went","been"],"answer_index":0,"explanation_cn":"has gone to = 去了那儿还没回来。✓ He has gone to the store; he''ll be back soon."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',10,NULL,'choice','{"stem":"\"Have you ever been to Canada?\" 是在问:","options":["你在加拿大吗","你去过加拿大吗","你想去加拿大吗","你要去加拿大吗"],"answer_index":1,"explanation_cn":"Have you ever been to Canada? 是在问\"你有没有去过加拿大\"。场合:聊旅行经历时问对方。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',10,NULL,'choice','{"stem":"\"I have just gotten your letter.\" 意思是:","options":["我读过你的信很多遍","我弄丢了你的信","我刚收到你的信","我要给你写信"],"answer_index":2,"explanation_cn":"I have just gotten your letter = 我刚刚收到你的信。场合:回复对方,告诉他信刚到手。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',10,NULL,'choice','{"stem":"Where has Tom moved?","options":["To Italy","Abroad, to Canada","Back to his hometown","To a village nearby"],"answer_index":1,"passage":"My brother Tom has moved abroad. He is now living in Canada, and he has been there for six months. I have just received a long letter from him. Tom is an engineer, and he has already gotten a good job at a big firm. He works hard, but he has not felt tired yet. Since he arrived, he has traveled to a great number of different cities. He has recently bought a used car. Right now he has driven to a small town in the center of the country. Have you ever been to Canada? Tom has never lived abroad before. He is finding this trip really exciting!","explanation_cn":"课文说 Tom has moved abroad… living in Canada,他搬到国外的加拿大了。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',10,NULL,'choice','{"stem":"How does Tom feel about the trip?","options":["He finds it very exciting","He wants to go home","He feels bored","He feels very tired"],"answer_index":0,"passage":"My brother Tom has moved abroad. He is now living in Canada, and he has been there for six months. I have just received a long letter from him. Tom is an engineer, and he has already gotten a good job at a big firm. He works hard, but he has not felt tired yet. Since he arrived, he has traveled to a great number of different cities. He has recently bought a used car. Right now he has driven to a small town in the center of the country. Have you ever been to Canada? Tom has never lived abroad before. He is finding this trip really exciting!","explanation_cn":"课文结尾 He is finding this trip really exciting,他觉得这趟旅行非常激动人心。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',10,NULL,'choice','{"stem":"What is Tom''s job?","options":["He is a driver","He is a teacher","He is a waiter","He is an engineer"],"answer_index":3,"audio":"My brother Tom has moved abroad. He is now living in Canada, and he has been there for six months. I have just received a long letter from him. Tom is an engineer, and he has already gotten a good job at a big firm. He works hard, but he has not felt tired yet. Since he arrived, he has traveled to a great number of different cities. He has recently bought a used car. Right now he has driven to a small town in the center of the country. Have you ever been to Canada? Tom has never lived abroad before. He is finding this trip really exciting!","explanation_cn":"课文说 Tom is an engineer,他是工程师。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l04',10,NULL,'choice','{"stem":"What has Tom recently bought?","options":["A bike","A used car","A new house","A boat"],"answer_index":1,"audio":"My brother Tom has moved abroad. He is now living in Canada, and he has been there for six months. I have just received a long letter from him. Tom is an engineer, and he has already gotten a good job at a big firm. He works hard, but he has not felt tired yet. Since he arrived, he has traveled to a great number of different cities. He has recently bought a used car. Right now he has driven to a small town in the center of the country. Have you ever been to Canada? Tom has never lived abroad before. He is finding this trip really exciting!","explanation_cn":"课文说 He has recently bought a used car,他最近买了一辆二手车。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l05',2,1,5,'No wrong numbers','无错号之虞','现在完成时(续)· up to now/so far 信号词 · a great many+可数复数 · since+时间点/从句 · 短暂动词不接一段时间 · 现在完成时↔一般过去时对话切换','叔叔 Jack 开第二家书店装不上电话 · 买十只鸽子在两店间送信 · 办起私人''鸽子邮递''业务','{"q":"Listen and answer — What has Jack bought to send messages?","options":["Ten pigeons","A telephone","A car","A computer"],"answer_index":0}'::jsonb,'{"title":"现在完成时(续):说''到现在为止'' & 报新闻","intro":"L4 学了现在完成时的构成,本课讲它的三个常用场合。全用本课句子举例。","table":{"headers":["用法 / 规则","本课例子"],"rows":[["up to now / so far / lately(到目前为止 / 最近)是现在完成时的信号词","Up to now, Jack has sent many messages."],["a great many + 可数名词复数(许多),只修饰可数复数","He has sent a great many requests."],["报''新消息''常用现在完成时开头,只讲事情本身、不点过去具体时间","He has just bought ten pigeons!"],["short 动词(buy/open/start…)的完成时不接''一段时间'';要说多久用 for/since 得配否定或延续动词","He hasn''t lost a message since he started.(否定可表持续)"]]},"specialRules":[{"rule":"一旦追问''什么时候''等过去具体情况,就从现在完成时改用一般过去时(—Have you seen it? —Yes. —When did you see it?)","mark":"新闻→追问"},{"rule":"有明确过去时间(last month / yesterday)只能用一般过去时,不能用现在完成时","mark":"vs 一般过去时"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l05',1,NULL,'My uncle Jack has owned a small bookstore downtown for years.','我叔叔 Jack 在市中心开了一家小书店,已经好多年了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l05',2,NULL,'Last month he opened a second store across the river.','上个月他在河对岸开了第二家店。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l05',3,NULL,'The new store is only two miles away.','新店离得只有两英里。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l05',4,NULL,'But the phone company hasn''t installed a phone line yet.','但电话公司还没给装电话线。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l05',5,NULL,'So my uncle has come up with a clever idea.','于是我叔叔想出了个妙招。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l05',6,NULL,'He has just bought ten pigeons!','他刚买了十只鸽子!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l05',7,NULL,'Yesterday, one pigeon carried his first note from the new store to the old one.','昨天,一只鸽子把他第一张便条从新店送到了老店。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l05',8,NULL,'The little bird covered the distance in just four minutes.','这只小鸟只用四分钟就飞完了全程。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l05',9,NULL,'Up to now, Jack has sent a great many requests and messages from one store to the other.','到目前为止,Jack 已经在两家店之间送了许多请求和信息。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l05',10,NULL,'He has never lost a single message.','他从没丢过一条信息。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l05',11,NULL,'In this way, he has started his own private "pigeon mail" service.','就这样,他办起了自己私人的"鸽子邮递"业务。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
