INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l05','up to now','',NULL,'/ʌp tə naʊ/','Up to now, Jack has sent many messages.','到目前为止,Jack 已经送了许多信息。','Up to now, I have read three books.','到目前为止,我已经读了三本书。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l05','a great many','',NULL,'/ə ɡreɪt ˈmeni/','He has sent a great many requests.','他已经送了许多请求。','A great many people use pigeons.','很多人用鸽子。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l05','come up with','',NULL,'/kʌm ʌp wɪð/','He has come up with a clever idea.','他想出了个妙招。','Can you come up with a better plan?','你能想出更好的办法吗?') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',5,'am2_l05_gp1','choice','{"stem":"\"He ___ started his own service.\"(主语 He)","options":["did","has","have","is"],"answer_index":1,"explanation_cn":"现在完成时 = have/has + 过去分词;主语 He(还有 she/it)用 has。✓ He has started his own service."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',5,'am2_l05_gp1','choice','{"stem":"\"They ___ sent many messages.\"(主语 They)","options":["has","is","have","was"],"answer_index":2,"explanation_cn":"主语 They(还有 I/you/we)用 have。✓ They have sent many messages."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',5,'am2_l05_gp2','choice','{"stem":"\"___ , Jack has sent many orders.\"(到目前为止)","options":["Next week","Long ago","Two days ago","Up to now"],"answer_index":3,"explanation_cn":"\"到目前为止\"用 Up to now,是现在完成时的信号词。✓ Up to now, Jack has sent many orders."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',5,'am2_l05_gp2','choice','{"stem":"\"Up to now, Mr. Scott ___ a great many messages.\"(填正确时态)","options":["has sent","sends","will send","sent"],"answer_index":0,"explanation_cn":"句首 Up to now 提示用现在完成时;主语 Mr. Scott 用 has + 过去分词 sent。✓ Up to now, Mr. Scott has sent a great many messages."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',5,'am2_l05_gp3','choice','{"stem":"\"He has sent a great many ___ .\"(许多信息)","options":["message","much message","a message","messages"],"answer_index":3,"explanation_cn":"a great many 后面接可数名词复数,所以用 messages。✓ a great many messages."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',5,'am2_l05_gp3','choice','{"stem":"a great many 后面接的是:","options":["不可数名词","形容词","可数名词复数","动词原形"],"answer_index":2,"explanation_cn":"a great many = 许多,只修饰可数名词复数(a great many messages / cities);修饰不可数名词要用 a great deal of。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',5,'am2_l05_gp4','choice','{"stem":"\"I haven''t heard from him ___ he left.\"(自从)","options":["for","during","when","since"],"answer_index":3,"explanation_cn":"\"自从(某个过去时间点/某事发生起)\"用 since。✓ I haven''t heard from him since he left."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',5,'am2_l05_gp4','choice','{"stem":"\"自从1990年\"用英语说:","options":["for 1990","from 1990 years","since 1990","since 1990 years"],"answer_index":2,"explanation_cn":"\"自从1990年(时间点)\"用 since 1990。✓ 注意不能说 for 1990,也不能说 since 1990 years(那要说 since 1990)。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',5,'am2_l05_gp5','choice','{"stem":"\"上个月他开了第二家店\"(有 last month)应说:","options":["He has opened a second store last month.","He opened a second store last month.","He has been opened a second store last month.","He opens a second store last month."],"answer_index":1,"explanation_cn":"有明确的过去时间 last month,只能用一般过去时 opened,不能用现在完成时。✓ He opened a second store last month."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',5,'am2_l05_gp5','choice','{"stem":"\"Yesterday I have finished it.\" 为什么错?","options":["有明确过去时间 yesterday,要用一般过去时(I finished it)","yesterday 要放句尾","have 要改成 has","finished 拼错了"],"answer_index":0,"explanation_cn":"yesterday 是明确的过去时间点,现在完成时不能和它连用;要改成一般过去时 I finished it yesterday。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',5,'am2_l05_gp6','choice','{"stem":"\"—Have you seen the new movie? —Yes, I have. —___ ?\"(接着问什么时候看的)","options":["When have you seen it?","When you saw it?","When do you see it?","When did you see it?"],"answer_index":3,"explanation_cn":"先用现在完成时报\"看过了\"(Yes, I have),接着追问\"什么时候看的\"就换成一般过去时。✓ When did you see it?"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',5,'am2_l05_gp6','choice','{"stem":"报新闻用现在完成时开头,接着追问\"什么时候\"时,时态要:","options":["换成现在进行时","换成一般过去时","换成一般将来时","还用现在完成时"],"answer_index":1,"explanation_cn":"报新消息时用现在完成时开头;一旦追问\"什么时候\"这种过去的具体情况,就改用一般过去时。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',5,'am2_l05_gp7','choice','{"stem":"\"He has just ___ ten pigeons.\"(buy 的过去分词)","options":["buyed","buy","buying","bought"],"answer_index":3,"explanation_cn":"buy 是不规则动词,过去分词是 bought。✓ He has just bought ten pigeons. 别写成 buyed。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',5,'am2_l05_gp7','choice','{"stem":"\"Jack has ___ his own service.\"(begin 的过去分词)","options":["beginning","begin","begun","began"],"answer_index":2,"explanation_cn":"begin 的过去分词是 begun(过去式是 began,别混)。✓ Jack has begun his own service."}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',5,'am2_l05_gp7','choice','{"stem":"\"He has ___ many messages by pigeon.\"(send 的过去分词)","options":["sent","sending","sended","send"],"answer_index":0,"explanation_cn":"send 是不规则动词,过去分词是 sent。✓ He has sent many messages. 别写成 sended。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',5,'am2_l05_gp8','choice','{"stem":"come up with 的意思是:","options":["放弃","想出(主意/办法)","赶上","走下来"],"answer_index":1,"explanation_cn":"come up with = 想出(主意、办法)。✓ He has come up with a clever idea."}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',5,'am2_l05_gp8','choice','{"stem":"\"The new store is only two miles ___ .\"(距离多远,与 away 义近)","options":["away","off from","far","long"],"answer_index":0,"explanation_cn":"\"离……多远\"用 miles away;away 表示\"距离(某处)\"。✓ The new store is only two miles away."}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',5,'am2_l05_gp8','choice','{"stem":"\"The bird covered the distance.\" 里 cover 的意思是:","options":["采访报道","掩盖真相","覆盖住","越过,走完(一段距离)"],"answer_index":3,"explanation_cn":"cover 在这里是\"越过、走完(一段距离)\"的意思。✓ The bird covered the distance in four minutes. 不是\"覆盖\"。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',6,NULL,'choice','{"stem":"美语里\"商店\"常用词是:","options":["booth","store","shop","stall"],"answer_index":1,"explanation_cn":"美语里\"商店\"常用 store(bookstore);英式常用 shop。✓ a small bookstore downtown."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',6,NULL,'choice','{"stem":"美语里\"市中心\"说:","options":["the middle city","city centre","downtown","midtown"],"answer_index":2,"explanation_cn":"美语里\"市中心\"说 downtown;英式说 (in the) city centre。✓ a bookstore downtown."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',6,NULL,'choice','{"stem":"美语里\"邮寄 / 信件\"用:","options":["mail","throw","carry","post"],"answer_index":0,"explanation_cn":"美语\"邮寄 / 信件\"用 mail;英式用 post。✓ his own private \"pigeon mail\" service."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',6,NULL,'choice','{"stem":"up to now 的意思是:","options":["马上","从今以后","很久以前","到目前为止"],"answer_index":3,"explanation_cn":"up to now = 到目前为止(和现在完成时连用)。✓ Up to now, he has sent many messages."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',6,NULL,'choice','{"stem":"a great many 的意思是:","options":["一点点","许多(修饰可数名词复数)","一半","大约"],"answer_index":1,"explanation_cn":"a great many = 许多,后面接可数名词复数。✓ a great many requests."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',6,NULL,'choice','{"stem":"come up with an idea 的意思是:","options":["站起来","放弃主意","想出一个主意","追上某人"],"answer_index":2,"explanation_cn":"come up with an idea = 想出一个主意/办法。✓ He has come up with a clever idea."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',7,NULL,'cloze','{"stem":"第 1 空","context":"My uncle Jack ___1___ a second store last month. The phone company hasn''t ___2___ a line yet, so he ___3___ bought ten pigeons. ___4___ now, Jack has sent many messages by pigeon.","blank_no":1,"options":["opened","has opened","opens","opening"],"answer_index":0,"explanation_cn":"有明确的过去时间 last month,用一般过去时 opened,不能用现在完成时。✓ He opened a second store last month."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',7,NULL,'cloze','{"stem":"第 2 空","context":"My uncle Jack ___1___ a second store last month. The phone company hasn''t ___2___ a line yet, so he ___3___ bought ten pigeons. ___4___ now, Jack has sent many messages by pigeon.","blank_no":2,"options":["installed","install","installing","installs"],"answer_index":0,"explanation_cn":"\"还没安装\"用现在完成时否定 hasn''t installed;install 的过去分词是 installed。✓ The phone company hasn''t installed a line yet."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',7,NULL,'cloze','{"stem":"第 3 空","context":"My uncle Jack ___1___ a second store last month. The phone company hasn''t ___2___ a line yet, so he ___3___ bought ten pigeons. ___4___ now, Jack has sent many messages by pigeon.","blank_no":3,"options":["has","have","had","is"],"answer_index":0,"explanation_cn":"主语 he 用 has + 过去分词。✓ He has bought ten pigeons."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',7,NULL,'cloze','{"stem":"第 4 空","context":"My uncle Jack ___1___ a second store last month. The phone company hasn''t ___2___ a line yet, so he ___3___ bought ten pigeons. ___4___ now, Jack has sent many messages by pigeon.","blank_no":4,"options":["Up to","For","Since","In"],"answer_index":0,"explanation_cn":"\"到目前为止\"是 Up to now,这里填 Up to。✓ Up to now, Jack has sent many messages."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',8,NULL,'choice','{"stem":"What has Jack bought to send messages?","options":["A computer","A telephone","Ten pigeons","A car"],"answer_index":2,"explanation_cn":"课文说 He has just bought ten pigeons,Jack 买了十只鸽子来送信。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',8,NULL,'choice','{"stem":"How far is the new store from the old one?","options":["Half a mile","Ten miles","Five minutes","Two miles"],"answer_index":3,"explanation_cn":"课文说 The new store is only two miles away,两家店相距两英里。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',8,NULL,'choice','{"stem":"When did Jack open his second store?","options":["Last month","This morning","A year ago","Yesterday"],"answer_index":0,"explanation_cn":"课文说 Last month he opened a second store,他上个月开的第二家店。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',9,NULL,'choice','{"stem":"你想告诉朋友一条新消息\"我刚买了辆新车\":","options":["I just buying a new car.","I just have bought a new car.","I have just buy a new car.","I have just bought a new car."],"answer_index":3,"explanation_cn":"报一条刚发生的新消息,用 have just + 过去分词。✓ I have just bought a new car. 场合:兴冲冲告诉朋友你的新鲜事。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',9,NULL,'choice','{"stem":"你想说\"到目前为止,我已经读了三本书\":","options":["Up to now, I read three books.","Up to now, I have read three books.","Up to now, I will read three books.","Up to now, I am reading three books."],"answer_index":1,"explanation_cn":"\"到目前为止一共做了多少\"用 up to now + 现在完成时。✓ Up to now, I have read three books. 场合:汇报自己到现在的进度。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',9,NULL,'choice','{"stem":"朋友说\"I have visited Japan.\",你想接着问\"你什么时候去的\":","options":["When did you go?","When you went?","When have you gone?","When do you go?"],"answer_index":0,"explanation_cn":"对方先说\"去过日本\"(现在完成时),你追问\"什么时候去的\"就换一般过去时。✓ When did you go? 场合:接着别人的话问具体时间。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',10,NULL,'choice','{"stem":"pigeon 的意思是:","options":["鸽子","麻雀","鸽笼","信封"],"answer_index":0,"explanation_cn":"pigeon = 鸽子。✓ He has bought ten pigeons."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',10,NULL,'choice','{"stem":"\"cover the distance\" 里 distance 的意思是:","options":["方向","距离","地址","速度"],"answer_index":1,"explanation_cn":"distance = 距离;cover the distance = 走完这段距离。✓ The bird covered the distance."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',10,NULL,'choice','{"stem":"\"Up to now, he ___ many letters.\"(填正确时态)","options":["has sent","sends","send","sent"],"answer_index":0,"explanation_cn":"句首 Up to now 提示用现在完成时;主语 he 用 has + 过去分词 sent。✓ Up to now, he has sent many letters."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',10,NULL,'choice','{"stem":"\"Last week I ___ a new phone.\"(有 last week)","options":["has bought","have bought","buy","bought"],"answer_index":3,"explanation_cn":"有明确过去时间 last week,用一般过去时 bought,不用现在完成时。✓ Last week I bought a new phone."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',10,NULL,'choice','{"stem":"\"The store has just opened!\" 是在说:","options":["那家店关门了","那家店明天开业","那家店刚刚开业(报新消息)","那家店很旧了"],"answer_index":2,"explanation_cn":"The store has just opened = 那家店刚刚开业,是在报一条新消息。场合:告诉别人附近新开了家店。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',10,NULL,'choice','{"stem":"别人说完 \"I have seen that movie\",你想问他什么时候看的,该说:","options":["When have you seen it?","When did you saw it?","When you see it?","When did you see it?"],"answer_index":3,"explanation_cn":"对方说\"看过那部电影\"后,你想问\"什么时候看的\",就用一般过去时问。✓ When did you see it? 场合:接着别人的话问细节。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',10,NULL,'choice','{"stem":"Why did Jack buy pigeons?","options":["Because the new store had no phone line","Because pigeons are cheap","Because he likes birds","Because he sells pigeons"],"answer_index":0,"passage":"My uncle Jack has owned a small bookstore downtown for years. Last month he opened a second store across the river. The new store is only two miles away. But the phone company hasn''t installed a phone line yet. So my uncle has come up with a clever idea. He has just bought ten pigeons! Yesterday, one pigeon carried his first note from the new store to the old one. The little bird covered the distance in just four minutes. Up to now, Jack has sent a great many requests and messages from one store to the other. He has never lost a single message. In this way, he has started his own private \"pigeon mail\" service.","explanation_cn":"课文说新店装不上电话(hasn''t installed a phone line),所以 Jack 才买鸽子送信。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',10,NULL,'choice','{"stem":"How long did the pigeon take to cover the distance?","options":["Three minutes","An hour","Two miles","Four minutes"],"answer_index":3,"passage":"My uncle Jack has owned a small bookstore downtown for years. Last month he opened a second store across the river. The new store is only two miles away. But the phone company hasn''t installed a phone line yet. So my uncle has come up with a clever idea. He has just bought ten pigeons! Yesterday, one pigeon carried his first note from the new store to the old one. The little bird covered the distance in just four minutes. Up to now, Jack has sent a great many requests and messages from one store to the other. He has never lost a single message. In this way, he has started his own private \"pigeon mail\" service.","explanation_cn":"课文说 The little bird covered the distance in just four minutes,鸽子只用四分钟。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',10,NULL,'choice','{"stem":"What service has Jack started?","options":["A delivery truck","A private ''pigeon mail'' service","A phone company","A taxi service"],"answer_index":1,"audio":"My uncle Jack has owned a small bookstore downtown for years. Last month he opened a second store across the river. The new store is only two miles away. But the phone company hasn''t installed a phone line yet. So my uncle has come up with a clever idea. He has just bought ten pigeons! Yesterday, one pigeon carried his first note from the new store to the old one. The little bird covered the distance in just four minutes. Up to now, Jack has sent a great many requests and messages from one store to the other. He has never lost a single message. In this way, he has started his own private \"pigeon mail\" service.","explanation_cn":"课文结尾 he has started his own private \"pigeon mail\" service,他办起了私人\"鸽子邮递\"业务。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l05',10,NULL,'choice','{"stem":"Where is Jack''s first bookstore?","options":["Downtown","Near the airport","In another city","Across the river"],"answer_index":0,"audio":"My uncle Jack has owned a small bookstore downtown for years. Last month he opened a second store across the river. The new store is only two miles away. But the phone company hasn''t installed a phone line yet. So my uncle has come up with a clever idea. He has just bought ten pigeons! Yesterday, one pigeon carried his first note from the new store to the old one. The little bird covered the distance in just four minutes. Up to now, Jack has sent a great many requests and messages from one store to the other. He has never lost a single message. In this way, he has started his own private \"pigeon mail\" service.","explanation_cn":"课文说 My uncle Jack has owned a small bookstore downtown,他第一家书店在市中心。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
